package app.cloudpath.githubvpn;

import org.junit.Test;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import static org.junit.Assert.*;

public class SessionCryptoTest {
    // Generated by this repository's real agent/seal.mjs, not by the Android implementation.
    private static final String PRIV = "AQIDBAUGBwgJCgsMDQ4PEBESExQVFhcYGRobHB0eHyA";
    private static final String PUB = "B6N8vBQgk8i3VdwbEOhstCY3StFqqFPtC9_AsrhtHHw";
    private static final String SID = "fixture_123456";
    private static final String EPK = "swSFwBeLozM1D0uCkfoM1Y2df0dLYR7EnGhsVNBZYGk";
    private static final String IV = "uE9OIZVZbsH_oZSj";
    private static final String CT = "xcaghbqQkek62c5Bt0auTWycvM36OXfmQwBuBmL-yCZKzuBalrJaCNY5eEskCt9OaHvt4Wvq5VHe18HJqG0xQRN5L4ckJX316PH6YIIZfR2d";

    @Test public void opensAgentEnvelope() throws Exception {
        SessionCrypto c = new SessionCrypto(SessionCrypto.decode(PRIV));
        assertEquals(PUB, c.publicKey());
        assertEquals("{\"v\":2,\"phase\":\"ready\",\"message\":\"آزمایش interoperability\"}",
                new String(c.open(SID, EPK, IV, CT), StandardCharsets.UTF_8));
    }
    @Test public void rejectsWrongSessionAndTampering() throws Exception {
        SessionCrypto c = new SessionCrypto(SessionCrypto.decode(PRIV));
        try { c.open("other_session", EPK, IV, CT); fail("wrong associated data must fail"); }
        catch (GeneralSecurityException expected) { }
        byte[] altered = SessionCrypto.decode(CT); altered[0] ^= 1;
        try { c.open(SID, EPK, IV, SessionCrypto.b64(altered)); fail("tampering must fail"); }
        catch (GeneralSecurityException expected) { }
        try { c.open(SID, EPK, "AA", CT); fail("bad IV must fail"); }
        catch (GeneralSecurityException expected) { }
    }
}
